"use strict";

document.addEventListener("DOMContentLoaded", async () => {
  const seriesName = "hcia-network-engineering";
  const params = new URLSearchParams(window.location.search);

  if (params.get("serie") !== seriesName) return;

  const promo = document.querySelector("[data-series-promo]");
  const panel = document.querySelector("[data-series-panel]");
  const generalQuiz = document.querySelector("[data-general-quiz]");
  const form = document.querySelector("[data-series-form]");
  const startScreen = document.querySelector("[data-series-start]");
  const questionsScreen = document.querySelector("[data-series-questions-screen]");
  const resultsScreen = document.querySelector("[data-series-results]");
  const questionRoot = document.querySelector("[data-series-question]");
  const progress = document.querySelector("[data-series-progress]");
  const currentQuestion = document.querySelector("[data-series-current]");
  const totalQuestions = document.querySelector("[data-series-total]");
  const previousButton = document.querySelector("[data-series-prev]");
  const nextButton = document.querySelector("[data-series-next]");
  const submitButton = document.querySelector("[data-series-submit]");
  const startButton = document.querySelector("[data-series-start-button]");
  const correctionButton = document.querySelector("[data-series-correction]");
  const restartButton = document.querySelector("[data-series-restart]");
  const scoreValue = document.querySelector("[data-series-score]");
  const scoreMax = document.querySelector("[data-series-score-max]");
  const percentageValue = document.querySelector("[data-series-percentage]");
  const scoreMessage = document.querySelector("[data-series-message]");

  promo?.setAttribute("hidden", "");
  generalQuiz?.setAttribute("hidden", "");
  panel?.removeAttribute("hidden");

  let questions = [];
  let answers = {};
  let currentIndex = 0;
  let correctionMode = false;
  let currentScreen = "start";

  const copy = {
    fr: {
      title: "HCIA-Datacom : ingénierie réseau",
      intro: "Répondez aux six questions une par une, puis consultez votre résultat et la correction détaillée.",
      generalLink: "Retour au quiz général",
      courseLink: "Revoir le cours",
      kicker: "Série ciblée · 6 questions",
      startTitle: "Prêt à vérifier vos acquis ?",
      startText: "Une seule question est affichée à la fois. Vos réponses sont conservées lorsque vous revenez en arrière.",
      startButton: "Commencer la série",
      question: "Question",
      multipleHint: "Plusieurs réponses sont possibles.",
      previous: "Précédent",
      next: "Suivant",
      finish: "Terminer",
      backToResults: "Retour aux résultats",
      resultsTitle: "Votre résultat",
      scoreLabel: "Votre score",
      correction: "Voir la correction",
      restart: "Recommencer",
      correct: "Correct !",
      incorrect: "À revoir.",
      explanation: "Explication :",
      excellent: "Excellent ! Vous maîtrisez les objectifs de cette unité.",
      good: "Très bien ! Une courte révision consolidera vos acquis.",
      average: "Bon début. Utilisez la correction pour reprendre les notions fragiles.",
      needsWork: "Reprenez les flashcards, puis tentez de nouveau la série.",
      loadError: "Impossible de charger cette série pour le moment."
    },
    en: {
      title: "HCIA-Datacom: Network Engineering",
      intro: "Answer the six questions one at a time, then review your result and the detailed correction.",
      generalLink: "Back to the general quiz",
      courseLink: "Review the course",
      kicker: "Focused series · 6 questions",
      startTitle: "Ready to check your knowledge?",
      startText: "Only one question is displayed at a time. Your answers are preserved when you go back.",
      startButton: "Start the series",
      question: "Question",
      multipleHint: "Select all answers that apply.",
      previous: "Previous",
      next: "Next",
      finish: "Finish",
      backToResults: "Back to results",
      resultsTitle: "Your result",
      scoreLabel: "Your score",
      correction: "View correction",
      restart: "Try again",
      correct: "Correct!",
      incorrect: "Review needed.",
      explanation: "Explanation:",
      excellent: "Excellent! You have mastered the objectives of this unit.",
      good: "Very good! A short review will consolidate your knowledge.",
      average: "Good start. Use the correction to revisit weaker concepts.",
      needsWork: "Review the flashcards, then try the series again.",
      loadError: "This series cannot be loaded at the moment."
    }
  };

  const getLanguage = () => document.querySelector("#lang")?.value === "en" ? "en" : "fr";
  const getCopy = () => copy[getLanguage()];
  const escapeHTML = (value) => String(value).replace(/[&<>"']/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  })[character]);
  const sameAnswers = (first, second) => {
    if (!Array.isArray(first) || !Array.isArray(second) || first.length !== second.length) return false;
    const sortedFirst = [...first].sort((a, b) => a - b);
    const sortedSecond = [...second].sort((a, b) => a - b);
    return sortedFirst.every((value, index) => value === sortedSecond[index]);
  };

  function isCorrect(question) {
    const answer = answers[question.id];
    return question.type === "multiple-choice"
      ? sameAnswers(answer || [], question.correctAnswers)
      : answer === question.correctAnswer;
  }

  function setScreen(screen) {
    currentScreen = screen;
    startScreen.hidden = screen !== "start";
    questionsScreen.hidden = screen !== "questions";
    resultsScreen.hidden = screen !== "results";
  }

  function updateCopy() {
    const text = getCopy();
    document.querySelector("[data-series-title]").textContent = text.title;
    document.querySelector("[data-series-intro]").textContent = text.intro;
    document.querySelector("[data-series-general-link]").textContent = text.generalLink;
    document.querySelector("[data-series-course-link]").textContent = text.courseLink;
    document.querySelector("[data-series-kicker]").textContent = text.kicker;
    document.querySelector("[data-series-start-title]").textContent = text.startTitle;
    document.querySelector("[data-series-start-text]").textContent = text.startText;
    startButton.textContent = text.startButton;
    document.querySelector("[data-series-question-label]").textContent = text.question;
    previousButton.textContent = text.previous;
    nextButton.textContent = text.next;
    document.querySelector("[data-series-results-title]").textContent = text.resultsTitle;
    document.querySelector("[data-series-score-label]").textContent = text.scoreLabel;
    correctionButton.textContent = text.correction;
    restartButton.textContent = text.restart;
  }

  function collectCurrentAnswer() {
    if (currentScreen !== "questions" || correctionMode || !questions.length) return;
    const question = questions[currentIndex];
    const checkedInputs = [...questionRoot.querySelectorAll('[name="series-answer"]:checked')];

    if (question.type === "multiple-choice") {
      answers[question.id] = checkedInputs.map((input) => Number(input.value));
    } else if (checkedInputs[0]) {
      answers[question.id] = Number(checkedInputs[0].value);
    } else {
      delete answers[question.id];
    }
  }

  function renderQuestion() {
    const language = getLanguage();
    const text = getCopy();
    const question = questions[currentIndex];
    const questionText = language === "en" ? question.questionEn : question.questionFr;
    const options = language === "en" ? question.optionsEn : question.optionsFr;
    const explanation = language === "en" ? question.explanationEN : question.explanationFR;
    const selectedAnswer = answers[question.id] ?? (question.type === "multiple-choice" ? [] : null);
    const inputType = question.type === "multiple-choice" ? "checkbox" : "radio";

    currentQuestion.textContent = String(currentIndex + 1);
    totalQuestions.textContent = String(questions.length);
    progress.style.width = `${((currentIndex + 1) / questions.length) * 100}%`;

    const optionsHTML = options.map((option, optionIndex) => {
      const checked = Array.isArray(selectedAnswer)
        ? selectedAnswer.includes(optionIndex)
        : selectedAnswer === optionIndex;
      let stateClass = "";

      if (correctionMode) {
        const correctOption = question.type === "multiple-choice"
          ? question.correctAnswers.includes(optionIndex)
          : question.correctAnswer === optionIndex;
        if (correctOption) stateClass = " correct-answer";
        else if (checked) stateClass = " wrong-answer";
      }

      return `<label class="option-label${stateClass}">
        <input type="${inputType}" name="series-answer" value="${optionIndex}" ${checked ? "checked" : ""} ${correctionMode ? "disabled" : ""}>
        <span class="option-text">${escapeHTML(option)}</span>
      </label>`;
    }).join("");

    let feedbackHTML = "";
    if (correctionMode) {
      const correct = isCorrect(question);
      feedbackHTML = `<div class="correction-status ${correct ? "correct" : "incorrect"}">${correct ? text.correct : text.incorrect}</div>
        <div class="explanation"><strong>${text.explanation}</strong>${escapeHTML(explanation)}</div>`;
    }

    questionRoot.innerHTML = `<div class="question quiz-series-question" role="group" aria-labelledby="series-question-title">
      <h4 class="question-text" id="series-question-title">${escapeHTML(questionText)}</h4>
      ${question.type === "multiple-choice" && !correctionMode ? `<p class="quiz-series-hint">${text.multipleHint}</p>` : ""}
      <div class="options-container">${optionsHTML}</div>
      ${feedbackHTML}
    </div>`;

    previousButton.disabled = currentIndex === 0;
    const lastQuestion = currentIndex === questions.length - 1;
    nextButton.hidden = lastQuestion;
    submitButton.hidden = !lastQuestion;
    submitButton.textContent = correctionMode ? text.backToResults : text.finish;
  }

  function showQuestions() {
    setScreen("questions");
    renderQuestion();
    panel.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  function showResults() {
    correctionMode = false;
    const text = getCopy();
    const score = questions.filter(isCorrect).length;
    const percentage = Math.round((score / questions.length) * 100);

    scoreValue.textContent = String(score);
    scoreMax.textContent = String(questions.length);
    percentageValue.textContent = `${percentage}%`;

    let message = text.needsWork;
    let messageClass = "needs-improvement";
    if (percentage >= 90) {
      message = text.excellent;
      messageClass = "excellent";
    } else if (percentage >= 70) {
      message = text.good;
      messageClass = "good";
    } else if (percentage >= 50) {
      message = text.average;
      messageClass = "average";
    }

    scoreMessage.className = `score-message ${messageClass}`;
    scoreMessage.textContent = message;
    setScreen("results");
    panel.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  startButton.addEventListener("click", () => {
    answers = {};
    currentIndex = 0;
    correctionMode = false;
    showQuestions();
  });

  previousButton.addEventListener("click", () => {
    collectCurrentAnswer();
    if (currentIndex > 0) {
      currentIndex -= 1;
      renderQuestion();
    }
  });

  nextButton.addEventListener("click", () => {
    collectCurrentAnswer();
    if (currentIndex < questions.length - 1) {
      currentIndex += 1;
      renderQuestion();
    }
  });

  submitButton.addEventListener("click", () => {
    if (correctionMode) {
      showResults();
      return;
    }
    collectCurrentAnswer();
    showResults();
  });

  correctionButton.addEventListener("click", () => {
    correctionMode = true;
    currentIndex = 0;
    showQuestions();
  });

  restartButton.addEventListener("click", () => {
    answers = {};
    currentIndex = 0;
    correctionMode = false;
    setScreen("start");
    panel.scrollIntoView({ behavior: "smooth", block: "start" });
  });

  document.addEventListener("tiansemi:i18n", () => {
    collectCurrentAnswer();
    updateCopy();
    if (currentScreen === "questions" && questions.length) renderQuestion();
    if (currentScreen === "results" && questions.length) showResults();
  });

  try {
    const response = await fetch(new URL("../../pages/quiz/questions1-20.json", window.location.href));
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    questions = (await response.json()).filter((question) => question.series === seriesName);
    if (!questions.length) throw new Error("Empty series");
    totalQuestions.textContent = String(questions.length);
    scoreMax.textContent = String(questions.length);
    updateCopy();
    setScreen("start");
  } catch (error) {
    console.error("Impossible de charger la série HCIA:", error);
    document.querySelector("[data-series-start-text]").textContent = getCopy().loadError;
    startButton.hidden = true;
  }
});
